"""Validation for files generated by a candidate solution."""

from __future__ import annotations

import csv
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

import pandas as pd
from PIL import Image

from .mask_io import load_mask
from .model_artifacts import validate_model_artifacts
from .prediction_contract import (
    load_prediction_contract,
    resolve_artifact_path,
)


@dataclass(frozen=True)
class ArtifactValidationResult:
    ok: bool
    messages: list[str]
    model_artifact: dict[str, Any] | None = None


def _resolve_artifact_path(workspace_dir: Path, value: str) -> Path:
    return resolve_artifact_path(workspace_dir, value)


def _canonical_working_ref(workspace_dir: Path, value: str) -> str:
    artifact_path = _resolve_artifact_path(workspace_dir, value)
    try:
        rel = artifact_path.resolve().relative_to((workspace_dir / "working").resolve())
    except ValueError:
        return value
    return str(Path("working") / rel)


def _normalize_csv_path_refs(workspace_dir: Path, csv_path: Path) -> list[str]:
    if not csv_path.is_file():
        return []

    df = pd.read_csv(csv_path)
    path_columns = [
        column
        for column in df.columns
        if "path" in column.lower() or "file" in column.lower()
    ]
    if not path_columns:
        return []

    changed = False
    for column in path_columns:
        new_values = []
        for value in df[column].tolist():
            if not isinstance(value, str) or not value.strip():
                new_values.append(value)
                continue
            normalized = _canonical_working_ref(workspace_dir, value)
            changed = changed or normalized != value
            new_values.append(normalized)
        df[column] = new_values

    if not changed:
        return []
    df.to_csv(csv_path, index=False)
    return [
        f"ArtifactNormalization: normalized working file references in {csv_path.name}"
    ]


def _submission_expected_rows(input_dir: Path) -> int | None:
    for path in [input_dir / "test.csv", input_dir / "test" / "metadata.csv"]:
        if path.is_file():
            return len(pd.read_csv(path))
    return None


def _patient_image_size_map(input_dir: Path) -> dict[str, tuple[int, int]]:
    metadata_path = input_dir / "test" / "metadata.csv"
    if not metadata_path.is_file():
        return {}

    metadata = pd.read_csv(metadata_path)
    if not {"patient", "image_path"}.issubset(metadata.columns):
        return {}

    sizes = {}
    for row in metadata.itertuples(index=False):
        image_path = input_dir / getattr(row, "image_path")
        if not image_path.is_file():
            continue
        with Image.open(image_path) as image:
            sizes[str(getattr(row, "patient"))] = image.size
    return sizes


def normalize_working_outputs(workspace_dir: Path | str, task_desc: str) -> list[str]:
    """Apply deterministic, task-format-only fixes to generated artifacts."""
    workspace_dir = Path(workspace_dir)
    working_dir = workspace_dir / "working"
    messages: list[str] = []
    for csv_path in sorted(working_dir.glob("*.csv")):
        messages.extend(_normalize_csv_path_refs(workspace_dir, csv_path))
    return messages


def validate_working_outputs(
    workspace_dir: Path | str,
    task_desc: str,
    *,
    candidate_code: str | None = None,
    model_probe: Callable[[str], Any] | None = None,
) -> ArtifactValidationResult:
    """Check common generated artifacts before the agent accepts a run."""
    predictions = _validate_prediction_outputs(workspace_dir, task_desc)
    if not predictions.ok:
        return predictions
    contract = load_prediction_contract(workspace_dir)
    model = validate_model_artifacts(
        workspace_dir,
        candidate_code=candidate_code,
        required=contract.raw.get("model_artifact_required") is True,
        model_probe=model_probe,
    )
    return ArtifactValidationResult(
        ok=model.ok,
        messages=predictions.messages + model.messages,
        model_artifact=model.evidence,
    )


def _validate_prediction_outputs(
    workspace_dir: Path | str, task_desc: str
) -> ArtifactValidationResult:
    workspace_dir = Path(workspace_dir)
    input_dir = workspace_dir / "input"
    contract = load_prediction_contract(workspace_dir)
    submission_path = contract.test_submission
    messages: list[str] = []

    test_split = workspace_dir / "input" / "biomaker_splits" / "agent_test.csv"
    expected_rows = (
        len(pd.read_csv(test_split))
        if test_split.is_file()
        else _submission_expected_rows(input_dir)
    )
    if expected_rows is not None and not submission_path.is_file():
        return ArtifactValidationResult(
            ok=False,
            messages=[
                "ArtifactValidationError: expected test submission because test data is present, but it was not created."
            ],
        )

    if not submission_path.is_file():
        return ArtifactValidationResult(ok=True, messages=[])

    submission = pd.read_csv(submission_path)
    if expected_rows is not None and len(submission) != expected_rows:
        messages.append(
            f"ArtifactValidationError: {submission_path.name} row count "
            f"({len(submission)}) does not match test data row count ({expected_rows})."
        )

    required_columns = [
        *contract.key_columns,
        *contract.prediction_columns,
    ]
    missing_columns = [
        column for column in required_columns if column not in submission
    ]
    if missing_columns:
        messages.append(
            "ArtifactValidationError: submission is missing required evaluator "
            "contract columns: " + ", ".join(missing_columns)
        )

    prediction_columns = set(contract.prediction_columns)
    declared_file_columns = set(contract.file_reference_columns)
    path_columns = [
        column
        for column in submission.columns
        if column in declared_file_columns
        or (
            column in prediction_columns
            and ("path" in column.lower() or "file" in column.lower())
        )
        or (
            not prediction_columns
            and ("path" in column.lower() or "file" in column.lower())
        )
    ]
    if not path_columns:
        return ArtifactValidationResult(ok=not messages, messages=messages)

    missing_paths = []
    invalid_masks = []

    with open(submission_path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            for column in path_columns:
                value = row.get(column) or ""
                if not value.strip():
                    missing_paths.append(f"{column}=<empty>")
                    continue

                artifact_path = _resolve_artifact_path(workspace_dir, value)
                if not artifact_path.is_file():
                    missing_paths.append(value)
                    continue

                if "mask" not in column.lower() and "mask" not in value.lower():
                    continue

                try:
                    load_mask(artifact_path)
                except Exception as exc:
                    invalid_masks.append(f"{value}: mask file is not readable: {exc}")

    if missing_paths:
        messages.append(
            "ArtifactValidationError: submission.csv references missing artifact files: "
            + ", ".join(missing_paths[:10])
        )
    if invalid_masks:
        messages.append("ArtifactValidationError: " + "; ".join(invalid_masks[:10]))

    return ArtifactValidationResult(ok=not messages, messages=messages)
